style.css:
@-moz-document url-prefix("https://www.roblox.com/") {
/* Fondo animado tipo neón celeste-azul */
  body::after {
    content: "";
    position: fixed;
    top: 0; left: 0;
    width: 100vw;
    height: 100vh;
    background: linear-gradient(270deg, #0dcaf0, #007bff, #00eaff, #00bcd4);
    background-size: 800% 800%;
    animation: animatedBackground 20s ease infinite;
    z-index: -9999;
    pointer-events: none;
  }

  @keyframes animatedBackground {
    0% {background-position: 0% 50%;}
    50% {background-position: 100% 50%;}
    100% {background-position: 0% 50%;}
  }

  /* Texto con sombra celeste animada */
  * {
    color: #ffffff !important;
    text-shadow: 0 0 6px #00eaff, 0 0 12px #00eaff !important;
    transition: text-shadow 0.5s ease-in-out;
  }

  *:hover {
    text-shadow: none !important;
  }

  /* Fondos oscuros para contenedores */
  .container-main,
  .content,
  .section,
  .game-card-container,
  .game-card,
  .left-col,
  .navbar,
  .content-container {
    background-color: rgba(10, 10, 10, 0.7) !important;
    border-radius: 12px !important;
  }

  /* Botones con efecto brillante */
  button, .btn-primary, .btn-secondary {
    background-color: #00eaff !important;
    color: #000 !important;
    border: none !important;
    box-shadow: 0 0 10px #00eaff !important;
    transition: transform 0.3s ease, box-shadow 0.3s ease;
  }

  button:hover {
    transform: scale(1.05);
    box-shadow: 0 0 20px #00eaff, 0 0 40px #00eaff;
  }

  /* Inputs estilizados */
  input, textarea {
    background-color: rgba(255, 255, 255, 0.05) !important;
    color: #ffffff !important;
    border: 1px solid #00eaff !important;
    border-radius: 6px !important;
  }

  /* Selección de texto azul */
  ::selection {
    background: #00eaff;
    color: #000;
  }
}
